package tests

import (
	"os/exec"
	"strings"
	"time"

	"github.com/VKCOM/nocc/internal/client"
)

func createClientAndEmulateDaemonForTesting(cmdLineStr string) (exitCode int, stdout []byte, stderr []byte, err error) {
	var cmdLine = strings.Split(cmdLineStr, " ")
	var remoteNoccHosts = []string{"127.0.0.1:43210"}
	var logFile = ""
	var logVerbosity = int64(-1)

	if err = client.MakeLoggerClient(logFile, logVerbosity, false); err != nil {
		return
	}

	exitCode, stdout, stderr = client.EmulateDaemonInsideThisProcessForDev(remoteNoccHosts, cmdLine, false, 0, 8*time.Minute)
	time.Sleep(100 * time.Millisecond) // for all goroutines to finish
	return
}

func runDaemonInBackgroundForTesting() error {
	cmd := exec.Command("../bin/nocc-daemon", "start")
	cmd.Env = []string{
		"NOCC_SERVERS=127.0.0.1:43210",
	}
	return cmd.Start()
}

func runCmdLocallyForTesting(cmdLineStr string) (exitCode int, output []byte, err error) {
	cmdLine := strings.Split(cmdLineStr, " ")

	cmd := exec.Command(cmdLine[0], cmdLine[1:]...)

	output, err = cmd.CombinedOutput()
	exitCode = cmd.ProcessState.ExitCode()
	return
}

package tests

// note, how to run this tests:
// 1) at first, start nocc-server available at 127.0.0.1:43210
// 2) then, run `go test` or these tests from IDE

import (
	"os"
	"testing"
)

func Test_compileMainCpp(t *testing.T) {
	var cmdLineStr = "g++ -include dt/cmake1/src/all-headers.h -c dt/cmake1/src/main.cpp -o /tmp/mm.o -Winvalid-pch -std=gnu++17"
	exitCode, stdout, stderr, err := createClientAndEmulateDaemonForTesting(cmdLineStr)
	if err != nil {
		t.Errorf("Error initing nocc client %s", err)
		return
	}

	if exitCode != 0 {
		t.Errorf("exitCode %d\nstdout %s\nstderr %s", exitCode, stdout, stderr)
		return
	}

	if len(stdout) > 0 {
		t.Logf("stdout %s\n", stdout)
	}
	if len(stderr) > 0 {
		t.Logf("stderr %s\n", stderr)
	}
}

func Test_compileCMakeProject1(t *testing.T) {
	if err := runDaemonInBackgroundForTesting(); err != nil {
		t.Error(err)
		return
	}

	cwd := "dt/cmake1"
	prevCwd, _ := os.Getwd()
	if err := os.Chdir(cwd); err != nil {
		t.Error(err)
		return
	}
	defer func() {
		_ = os.Chdir(prevCwd)
	}()

	err := os.RemoveAll("build")
	if err != nil {
		t.Error(err)
		return
	}

	exitCode, output, err := runCmdLocallyForTesting("bash build.sh")
	if err != nil {
		t.Error(err)
		return
	}
	if exitCode != 0 {
		t.Errorf("exitCode %d\n%s", exitCode, output)
		return
	}

	if len(output) > 0 {
		t.Logf("output %s\n", output)
	}
}

func Test_compileCppFileInUsrLocal(t *testing.T) {
	// this test supposes you have the following files:
	// * /usr/local/nocc-test.cpp    			, it does #include "nocc-test.h"
	// * /usr/local/nocc-test/nocc-test.h
	// here we test, that besides these files aren't uploaded (and aren't saved to /tmp/.../usr/local/),
	// they still compile correctly and -I option points to a system path, not to a non-existing tmp path
	if _, err := os.Stat("/usr/local/nocc-test.cpp"); err != nil {
		t.Skip("/usr/local/nocc-test.cpp doesn't exist")
		return
	}

	var cmdLineStr = "g++ -c /usr/local/nocc-test.cpp -I/usr/local/nocc-test/ -o /tmp/usr-local-nocc-test.o"
	exitCode, stdout, stderr, err := createClientAndEmulateDaemonForTesting(cmdLineStr)
	if err != nil {
		t.Errorf("Error initing nocc client %s", err)
		return
	}

	if exitCode != 0 {
		t.Errorf("exitCode %d\nstdout %s\nstderr %s", exitCode, stdout, stderr)
		return
	}

	if len(stdout) > 0 {
		t.Logf("stdout %s\n", stdout)
	}
	if len(stderr) > 0 {
		t.Logf("stderr %s\n", stderr)
	}
}

func Test_relativePathMacro(t *testing.T) {
	var cmdLineStr = "g++ -c dt/path-macro.cpp -o dt/path-macro.o -std=gnu++17"
	exitCode, stdout, stderr, err := createClientAndEmulateDaemonForTesting(cmdLineStr)
	if err != nil {
		t.Errorf("Error initing nocc client %s", err)
		return
	}

	if exitCode != 0 {
		t.Errorf("exitCode %d\nstdout %s\nstderr %s", exitCode, stdout, stderr)
		return
	}

	if len(stdout) > 0 {
		t.Logf("stdout %s\n", stdout)
	}
	if len(stderr) > 0 {
		t.Logf("stderr %s\n", stderr)
	}

	exitCode, stdout, err = runCmdLocallyForTesting("g++ dt/path-macro.o -o /tmp/path-macro -std=gnu++17")
	if err != nil || exitCode != 0 {
		t.Errorf("exitCode %d\n%s", exitCode, stdout)
		return
	}

	if len(stdout) > 0 {
		t.Logf("stdout %s\n", stdout)
	}

	exitCode, stdout, err = runCmdLocallyForTesting("/tmp/path-macro")
	if err != nil || exitCode != 0 {
		t.Errorf("exitCode %d\n%s", exitCode, stdout)
		return
	}

	if len(stdout) > 0 {
		t.Logf("stdout %s\n", stdout)
	}

	if string(stdout) != "dt/path-macro.cpp\n" {
		t.Errorf("%s", stdout)
	}
}

package tests

// note, how to run this tests:
// 1) at first, start nocc-server available at 127.0.0.1:43210
// 2) then, run `go test` or these tests from IDE

import (
	"fmt"
	"os"
	"path"
	"path/filepath"
	"strings"
	"syscall"
	"testing"

	"github.com/VKCOM/nocc/internal/client"
	"github.com/VKCOM/nocc/internal/common"
)

func compareTwoDepfiles(lhs *client.DepFile, rhs *client.DepFile, lhsDesc string, rhsDesc string) []string {
	normalizeDepItem := func(depItem string) string {
		if !strings.Contains(depItem, ".") {
			return depItem
		}
		return strings.TrimPrefix(path.Clean(depItem), "../tests/")
	}

	diff := make([]string, 0)
	for _, rhsTarget := range rhs.DTargets {
		targetName := rhsTarget.TargetName
		rhsDeps := rhsTarget.TargetDepList
		lhsDeps := lhs.FindDepListByTargetName(targetName)
		if lhsDeps == nil {
			diff = append(diff, fmt.Sprintf("Target '%s' exists in %s but not in %s", targetName, rhsDesc, lhsDesc))
			continue
		}

	outer:
		for _, rhsDep := range rhsDeps {
			for _, lhsDep := range lhsDeps {
				if normalizeDepItem(rhsDep) == normalizeDepItem(lhsDep) {
					continue outer
				}
			}
			diff = append(diff, fmt.Sprintf("Item '%s' for target '%s' exists in %s but not in %s", rhsDep, targetName, rhsDesc, lhsDesc))
		}
	}
	return diff
}

func runGccWithNoccAndCompareOutputDepfiles(t *testing.T, cmdLineStr string, dirToClear string, expectedOutDFileName string) {
	for _, pattern := range []string{"*.o", "*.d"} {
		files, _ := filepath.Glob(dirToClear + "/" + pattern)
		for _, relFn := range files {
			_ = syscall.Unlink(relFn)
		}
	}

	exitCode, output, err := runCmdLocallyForTesting(cmdLineStr)
	if err != nil {
		t.Errorf("Error run gcc %v\n%s", err, output)
		return
	}
	if exitCode != 0 {
		t.Errorf("Gcc exitCode %d\n%s", exitCode, output)
		return
	}

	gccDepsOut, err := client.MakeDepFileFromFile(expectedOutDFileName)
	if err != nil {
		t.Errorf("Error parsing %s after g++: %v", expectedOutDFileName, err)
		return
	}
	_ = os.Rename(expectedOutDFileName, common.ReplaceFileExt(expectedOutDFileName, ".gcc.d"))

	exitCode, stdout, stderr, err := createClientAndEmulateDaemonForTesting(cmdLineStr)
	if err != nil {
		t.Errorf("Error initing nocc client %v", err)
		return
	}
	if exitCode != 0 {
		t.Errorf("Nocc client exitCode %d\nstdout %s\nstderr %s", exitCode, stdout, stderr)
		return
	}
	noccDepsOut, err := client.MakeDepFileFromFile(expectedOutDFileName)
	if err != nil {
		t.Errorf("Error parsing %s after nocc: %v", expectedOutDFileName, err)
		return
	}

	errors := compareTwoDepfiles(noccDepsOut, gccDepsOut, expectedOutDFileName, "gcc")
	if len(errors) != 0 {
		t.Errorf("Diff if d contents:\n%s", strings.Join(errors, "\n"))
	}
}

func Test_MDMTMFMP(t *testing.T) {
	var cmdLineStr = "g++ -MD -MT dt/dep1/1.cpp.o -MF dt/dep1/1.cpp.o.d -o dt/dep1/1.cpp.o -c dt/dep1/1.cpp -MP"
	runGccWithNoccAndCompareOutputDepfiles(t, cmdLineStr, "dt/dep1", "dt/dep1/1.cpp.o.d")
}

func Test_MDMTMFMPMMD(t *testing.T) {
	var cmdLineStr = "g++ -MD -MT dt/dep1/1.cpp.o -MF dt/dep1/1.cpp.o.d -o dt/dep1/1.cpp.o -c dt/dep1/1.cpp -MP -MMD"
	runGccWithNoccAndCompareOutputDepfiles(t, cmdLineStr, "dt/dep1", "dt/dep1/1.cpp.o.d")
}

func Test_MDMF(t *testing.T) {
	var cmdLineStr = "g++ -MD -MF dt/dep1/1.cpp.o.d -o../tests/dt/dep1/1111.cpp.o ../tests/./dt/dep1/1.cpp"
	runGccWithNoccAndCompareOutputDepfiles(t, cmdLineStr, "dt/dep1", "dt/dep1/1.cpp.o.d")
}

func Test_MQMQMQMQMMP(t *testing.T) {
	var cmdLineStr = "g++ -MD -MF dt/dep1/out.d -MQ $(#func.k) -MQ some/long/long/long/long/option/will/be/placed/on/next/line/func.o -MQ func.i -MQ $(#func.j) -o dt/dep1/1111.cpp.o dt/./dep1/1.cpp -MMD"
	runGccWithNoccAndCompareOutputDepfiles(t, cmdLineStr, "dt/dep1", "dt/dep1/out.d")
}

func Test_MTMTMTMTMMP(t *testing.T) {
	var cmdLineStr = "g++ -MD -MF dt/dep1/out.d -MT $(#func.k) -MT some/long/long/long/long/option/will/be/placed/on/next/line/func.o -MT func.i -MT $(#func.j) -o dt/dep1/1111.cpp.o dt/./dep1/1.cpp -MMD"
	runGccWithNoccAndCompareOutputDepfiles(t, cmdLineStr, "dt/dep1", "dt/dep1/out.d")
}

func Test_parseDepFile(t *testing.T) {
	var dFileName = "dt/some_complex_depfile.o.d"
	depFile, err := client.MakeDepFileFromFile(dFileName)
	if err != nil {
		t.Error(err)
		return
	}

	exported := depFile.WriteToBytes()
	imported, err := client.MakeDepFileFromBytes(exported)
	if err != nil {
		t.Error(err)
		return
	}

	diff1 := compareTwoDepfiles(depFile, imported, "orig depfile", "imported from string")
	if len(diff1) > 0 {
		t.Errorf(strings.Join(diff1, "\n"))
	}

	diff2 := compareTwoDepfiles(imported, depFile, "imported from string", "orig depfile")
	if len(diff2) > 0 {
		t.Errorf(strings.Join(diff2, "\n"))
	}
}

package server

import (
	"fmt"
	"os"
	"path"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// ClientsStorage contains all active clients connected to this server.
// After a client is not active for some time, it's deleted (and its working directory is removed from a hard disk).
type ClientsStorage struct {
	table map[string]*Client
	mu    sync.RWMutex

	clientsDir string // /tmp/nocc/cpp/clients

	completedCount       int64
	lastPurgeTime        time.Time
	checkInactiveTimeout time.Duration

	uniqueRemotesList map[string]string
}

func MakeClientsStorage(clientsDir string, checkInactiveTimeout time.Duration) (*ClientsStorage, error) {
	return &ClientsStorage{
		table:                make(map[string]*Client, 1024),
		clientsDir:           clientsDir,
		uniqueRemotesList:    make(map[string]string, 1),
		checkInactiveTimeout: checkInactiveTimeout,
	}, nil
}

func (allClients *ClientsStorage) GetClient(clientID string) *Client {
	allClients.mu.RLock()
	client := allClients.table[clientID]
	allClients.mu.RUnlock()

	return client
}

func (allClients *ClientsStorage) OnClientConnected(clientID string, disableObjCache bool) (*Client, error) {
	allClients.mu.RLock()
	client := allClients.table[clientID]
	allClients.mu.RUnlock()

	// rpc query /StartClient is sent exactly once by nocc-daemon
	// if this clientID exists in table, this means a previous interrupted nocc-daemon launch
	// in this case, delete an old hanging client, closing all channels and streams — and create a new instance
	if client != nil {
		logServer.Info(0, "client reconnected, re-creating", "clientID", clientID)
		allClients.DeleteClient(client)
	}

	workingDir := path.Join(allClients.clientsDir, clientID)
	if err := os.Mkdir(workingDir, os.ModePerm); err != nil {
		return nil, fmt.Errorf("can't create client working directory: %v", err)
	}

	client = &Client{
		clientID:          clientID,
		workingDir:        workingDir,
		lastSeen:          time.Now(),
		sessions:          make(map[uint32]*Session, 20),
		files:             make(map[string]*fileInClientDir, 1024),
		dirs:              make(map[string]bool, 100),
		chanDisconnected:  make(chan struct{}),
		chanReadySessions: make(chan *Session, 200),
		disableObjCache:   disableObjCache,
	}

	allClients.mu.Lock()
	allClients.table[clientID] = client
	allClients.mu.Unlock()
	return client, nil
}

func (allClients *ClientsStorage) DeleteClient(client *Client) {
	allClients.mu.Lock()
	delete(allClients.table, client.clientID)
	allClients.mu.Unlock()
	atomic.AddInt64(&allClients.completedCount, 1)

	close(client.chanDisconnected)
	// don't close chanReadySessions intentionally, it's not a leak
	client.RemoveWorkingDir()
}

func (allClients *ClientsStorage) DeleteInactiveClients() {
	now := time.Now()
	if now.Sub(allClients.lastPurgeTime) < time.Minute {
		return
	}

	for {
		var inactiveClient *Client = nil
		allClients.mu.RLock()
		for _, client := range allClients.table {
			if now.Sub(client.lastSeen) > allClients.checkInactiveTimeout {
				inactiveClient = client
				break
			}
		}
		allClients.mu.RUnlock()
		if inactiveClient == nil {
			break
		}

		logServer.Info(0, "delete inactive client", "clientID", inactiveClient.clientID, "num files", inactiveClient.FilesCount(), "; nClients", allClients.ActiveCount()-1)
		allClients.DeleteClient(inactiveClient)
	}
}

func (allClients *ClientsStorage) StopAllClients() {
	allClients.mu.Lock()
	for _, client := range allClients.table {
		// do not call DeleteClient(), since the server is stopping, removing working dir is not needed
		close(client.chanDisconnected)
	}

	allClients.table = make(map[string]*Client)
	allClients.mu.Unlock()
}

func (allClients *ClientsStorage) ActiveCount() int64 {
	allClients.mu.RLock()
	clientsCount := len(allClients.table)
	allClients.mu.RUnlock()
	return int64(clientsCount)
}

func (allClients *ClientsStorage) CompletedCount() int64 {
	return atomic.LoadInt64(&allClients.completedCount)
}

func (allClients *ClientsStorage) ActiveSessionsCount() int64 {
	allClients.mu.RLock()
	sessionsCount := 0
	for _, client := range allClients.table {
		sessionsCount += client.GetActiveSessionsCount()
	}
	allClients.mu.RUnlock()
	return int64(sessionsCount)
}

func (allClients *ClientsStorage) TotalFilesCountInDirs() int64 {
	var filesCount int64 = 0
	allClients.mu.RLock()
	for _, client := range allClients.table {
		filesCount += client.FilesCount()
	}
	allClients.mu.RUnlock()
	return filesCount
}

// IsRemotesListSeenTheFirstTime maintains allClients.uniqueRemotesList.
// It's mostly for debug purposes — to detect clients with strange NOCC_SERVERS env.
// Probably, will be deleted in the future.
func (allClients *ClientsStorage) IsRemotesListSeenTheFirstTime(allRemotesDelim string, clientID string) bool {
	allClients.mu.RLock()
	_, exists := allClients.uniqueRemotesList[allRemotesDelim]
	allClients.mu.RUnlock()

	if !exists {
		allClients.mu.Lock()
		allClients.uniqueRemotesList[allRemotesDelim] = clientID
		allClients.mu.Unlock()
	}

	return !exists
}

func (allClients *ClientsStorage) GetUniqueRemotesListInfo() (uniqueInfo []string) {
	allClients.mu.RLock()

	uniqueInfo = make([]string, 0, len(allClients.uniqueRemotesList))
	for allRemotesDelim, clientID := range allClients.uniqueRemotesList {
		nRemotes := strings.Count(allRemotesDelim, ",") + 1
		uniqueInfo = append(uniqueInfo, fmt.Sprintf("(n=%d) clientID %s : %s", nRemotes, clientID, allRemotesDelim))
	}

	allClients.mu.RUnlock()
	return
}

package server

import (
	"math/rand"
	"os"
	"strconv"
)

// SrcFileCache is a /tmp/nocc/cpp/src-cache directory, where uploaded .cpp/.h/etc. files are saved.
// It's supposed that sha256 uniquely identifies the file, that's why a map key doesn't contain size/mtime.
// It's useful to share files across clients (if one client has uploaded a file, the second takes it from cache).
// Also, it helps reuse files across the same client after it was considered inactive and deleted, but launched again.
type SrcFileCache struct {
	*FileCache
}

func MakeSrcFileCache(cacheDir string, limitBytes int64) (*SrcFileCache, error) {
	cache, err := MakeFileCache(cacheDir, limitBytes)
	if err != nil {
		return nil, err
	}

	return &SrcFileCache{cache}, nil
}

func (cache *SrcFileCache) MakeTempFileForUploadSaving(serverFileName string) (*os.File, error) {
	// path.Dir(serverFileName) is created in advance, see Client.MkdirAllForSession()
	fileNameTmp := serverFileName + "." + strconv.Itoa(rand.Int())
	return os.OpenFile(fileNameTmp, os.O_RDWR|os.O_CREATE|os.O_EXCL, os.ModePerm)
}

package server

import (
	"crypto/sha256"
	"fmt"
	"path"
	"strings"

	"github.com/VKCOM/nocc/internal/common"
)

// ObjFileCache is a /tmp/nocc/obj/obj-cache directory, where the resulting .o files are saved.
// Its purpose is to reuse a ready .o file if the same .cpp is requested to be compiled again.
// This is especially useful to share .o files across build agents:
// if one build agent compiles the master branch, other build agents can reuse ready .o for every .cpp.
// The hardest problem is how to detect that "this .cpp was already compiled, we can use .o".
// See ObjFileCache.MakeObjCacheKey.
type ObjFileCache struct {
	*FileCache

	// next to obj-cache, there is a /tmp/nocc/obj/cxx-out directory (session.objOutFile point here)
	// after being compiled, files from here are hard linked to obj-cache
	objTmpDir string
}

func MakeObjFileCache(cacheDir string, objTmpDir string, limitBytes int64) (*ObjFileCache, error) {
	cache, err := MakeFileCache(cacheDir, limitBytes)
	if err != nil {
		return nil, err
	}

	return &ObjFileCache{cache, strings.TrimSuffix(objTmpDir, "/")}, nil
}

// MakeObjCacheKey creates a unique key (sha256) for an input .cpp file and all its dependencies.
// If this exact .cpp file with these exact dependencies was already compiled (even by another client),
// we can reuse stored .o and respond immediately, without actual cxx invocation.
//
// Cxx compilation depends not only on files, but on other options too, the final cxxCmdLine looks like
// > g++ -Wall -fpch-preprocess ... -iquote /tmp/client1/headers -o /tmp/client1/some.cpp.123.o /tmp/client1/some.cpp
// We want to reuse a ready .o file if and only if:
// * the .cpp file is the same (its name and sha256)
// * all dependent .h/.nocc-pch/etc. are the same (their count, order, size, sha256)
// * all C++ compiler options are the same
//
// The problem is with the last point. cxxCmdLine contains -I and other options that vary between clients:
// > -iquote /tmp/nocc/cpp/clients/{clientID}/home/{username}/proj -I /tmp/gch/{random_hash} -o ...{random_int}.o
// These are different options, but in fact, they should be considered the same.
// That's why we don't take include paths into account when calculating a hash from cxxCmdLine.
// The assumption is: if all deps are equal, their actual paths/names don't matter.
func (cache *ObjFileCache) MakeObjCacheKey(cxxName string, cxxArgs []string, sessionFiles []*fileInClientDir, cppInFile string) common.SHA256 {
	hasher := sha256.New()

	hasher.Write([]byte(cxxName))
	for _, arg := range cxxArgs {
		hasher.Write([]byte(arg))
	}
	hasher.Write([]byte(path.Base(cppInFile))) // not a full path, as it varies between clients

	sha256xor := common.MakeSHA256Struct(hasher)
	sha256xor.B8_15 ^= uint64(len(cxxArgs))
	sha256xor.B16_23 ^= uint64(len(sessionFiles))
	for _, file := range sessionFiles {
		sha256xor.XorWith(&file.fileSHA256)
		sha256xor.B0_7 ^= uint64(file.fileSize)
	}

	return sha256xor
}

// GenerateObjOutFileName generates session.objOutFile (destination for C++ compiler launched on a server)
func (cache *ObjFileCache) GenerateObjOutFileName(session *Session) string {
	return fmt.Sprintf("%s/%s.%d.o", cache.objTmpDir, session.client.clientID, session.sessionID)
}

package client

import (
	"sync"

	"github.com/VKCOM/nocc/internal/common"
)

type includeCachedHFile struct {
	fileSize       int64         // size of file; -1 means that a file doesn't exist
	fileSHA256     common.SHA256 // hash of contents (but for pch it's a combined hash of dependencies)
	nestedIncludes []string      // [ /abs/path/to/sub/included_file.h, ... ] in order of appearance
}

// IncludesCache represents a structure that is kept in memory while the daemon is running.
// It helps reduce hard disk lookups for #include resolving.
type IncludesCache struct {
	// g++ / clang / etc. — detected on daemon start, on first `nocc` invocation
	cxxName string
	// default include dirs for current cxxName
	cxxDefIDirs IncludeDirs
	// how #include <math.h> is resolved to an /actual/path/to/math.h
	includesResolve map[string]string
	// properties of /actual/path/to/math.h (file/sha256 and nested #include list)
	hFilesInfo map[string]*includeCachedHFile

	mu sync.RWMutex
}

func MakeIncludesCache(cxxName string) (*IncludesCache, error) {
	cxxDefIDirs, err := GetDefaultCxxIncludeDirsOnLocal(cxxName)

	return &IncludesCache{
		cxxName:         cxxName,
		cxxDefIDirs:     cxxDefIDirs,
		includesResolve: make(map[string]string),
		hFilesInfo:      make(map[string]*includeCachedHFile),
	}, err
}

func (incCache *IncludesCache) GetIncludeResolve(quotedArg string) (hFileName string, exists bool) {
	if quotedArg[0] == '/' {
		hFileName, exists = quotedArg, true
		return
	}
	incCache.mu.RLock()
	hFileName, exists = incCache.includesResolve[quotedArg]
	incCache.mu.RUnlock()
	return
}

func (incCache *IncludesCache) AddIncludeResolve(quotedArg string, hFileName string) {
	incCache.mu.Lock()
	incCache.includesResolve[quotedArg] = hFileName
	incCache.mu.Unlock()
}

func (incCache *IncludesCache) GetHFileInfo(hFileName string) (hFileCached *includeCachedHFile, exists bool) {
	incCache.mu.RLock()
	hFileCached, exists = incCache.hFilesInfo[hFileName]
	incCache.mu.RUnlock()
	return
}

func (incCache *IncludesCache) AddHFileInfo(hFileName string, fileSize int64, fileSHA256 common.SHA256, nestedIncludes []string) {
	incCache.mu.Lock()
	incCache.hFilesInfo[hFileName] = &includeCachedHFile{fileSize, fileSHA256, nestedIncludes}
	incCache.mu.Unlock()
}

func (incCache *IncludesCache) Count() int {
	incCache.mu.RLock()
	count := len(incCache.hFilesInfo)
	incCache.mu.RUnlock()
	return count
}

func (incCache *IncludesCache) Clear() {
	incCache.mu.Lock()
	incCache.includesResolve = make(map[string]string)
	incCache.hFilesInfo = make(map[string]*includeCachedHFile)
	incCache.mu.Unlock()
}

package server

import (
	"fmt"
	"os"
	"path"
	"sync"
	"sync/atomic"

	"github.com/VKCOM/nocc/internal/common"
)

type cachedFile struct {
	pathInCache string // /tmp/full/path/to/file.ext
	fileSize    int64
	lruNode     *lruNode
}

type lruNode struct {
	next, prev *lruNode
	key        common.SHA256
}

// FileCache is a base for ObjFileCache and SrcFileCache, see comments for them.
// It's a directory stored somewhere in /tmp where files could be saved and retrieved back by sha256.
// It's limited in size by lru (when its size exceeds a limit, the oldest accessed file is deleted).
// "Restoring from cache" is just a hard link to a new path.
type FileCache struct {
	table            map[common.SHA256]cachedFile
	lruTail, lruHead *lruNode
	mu               sync.RWMutex

	lastIndex   int64 // nb! atomic
	purgedCount int64 // nb! atomic
	cacheDir    string

	totalSizeOnDisk int64 // nb! atomic
	hardLimit       int64
	softLimit       int64
}

const shardsDirCount = 256

func createSubdirsForFileCache(cacheDir string) error {
	for i := 0; i < shardsDirCount; i++ {
		dir := path.Join(cacheDir, fmt.Sprintf("%X", i))
		if err := os.Mkdir(dir, os.ModePerm); err != nil {
			return err
		}
	}
	return nil
}

func MakeFileCache(cacheDir string, limitBytes int64) (*FileCache, error) {
	if err := createSubdirsForFileCache(cacheDir); err != nil {
		return nil, err
	}

	return &FileCache{
		table:     make(map[common.SHA256]cachedFile, 128*1024),
		cacheDir:  cacheDir,
		hardLimit: limitBytes,
		softLimit: int64(80.0 * (float64(limitBytes) / 100.0)),
	}, nil
}

func (cache *FileCache) LookupInCache(key common.SHA256) string {
	cache.mu.Lock()
	cachedFile := cache.table[key]
	if cachedFile.lruNode != nil && cachedFile.lruNode != cache.lruHead {
		// cachedFile.lruNode != cache.lruHead => cachedFile.lruNode.prev != nil
		cachedFile.lruNode.prev.next = cachedFile.lruNode.next
		if cachedFile.lruNode.next == nil {
			// cachedFile.lruNode.next == nil => cachedFile.lruNode == cache.lruTail
			cache.lruTail = cachedFile.lruNode.prev
		} else {
			cachedFile.lruNode.next.prev = cachedFile.lruNode.prev
		}

		cachedFile.lruNode.prev = nil
		cachedFile.lruNode.next = cache.lruHead

		cache.lruHead.prev = cachedFile.lruNode
		cache.lruHead = cachedFile.lruNode
	}
	cache.mu.Unlock()

	return cachedFile.pathInCache // empty if cachedFile doesn't exist
}

func (cache *FileCache) CreateHardLinkFromCache(serverFileName string, key common.SHA256) bool {
	pathInCache := cache.LookupInCache(key)
	if len(pathInCache) == 0 {
		return false
	}

	// path.Dir(serverFileName) must be created in advance
	err := os.Link(pathInCache, serverFileName)
	return err == nil || os.IsExist(err)
}

func (cache *FileCache) SaveFileToCache(srcPath string, fileNameInCacheDir string, key common.SHA256, fileSize int64) error {
	uniqueID := atomic.AddInt64(&cache.lastIndex, 1)
	pathInCache := fmt.Sprintf("%s/%X/%s.%X", cache.cacheDir, uniqueID%shardsDirCount, fileNameInCacheDir, uniqueID)

	if err := os.Link(srcPath, pathInCache); err != nil {
		return err
	}

	newHead := &lruNode{key: key}
	value := cachedFile{pathInCache, fileSize, newHead}
	cache.mu.Lock()
	_, exists := cache.table[key]
	if !exists {
		atomic.AddInt64(&cache.totalSizeOnDisk, fileSize)
		cache.table[key] = value
		newHead.next = cache.lruHead
		if cache.lruHead != nil {
			cache.lruHead.prev = newHead
		}
		cache.lruHead = newHead
		if cache.lruTail == nil {
			cache.lruTail = newHead
		}
	}
	cache.mu.Unlock()

	if exists {
		_ = os.Remove(pathInCache)
	}

	cache.purgeLastElementsTillLimit(cache.hardLimit)
	return nil
}

func (cache *FileCache) PurgeLastElementsIfRequired() {
	cache.purgeLastElementsTillLimit(cache.softLimit)
}

func (cache *FileCache) GetFilesCount() int64 {
	cache.mu.Lock()
	elements := len(cache.table)
	cache.mu.Unlock()
	return int64(elements)
}

func (cache *FileCache) GetBytesOnDisk() int64 {
	return atomic.LoadInt64(&cache.totalSizeOnDisk)
}

func (cache *FileCache) GetPurgedFilesCount() int64 {
	return atomic.LoadInt64(&cache.purgedCount)
}

func (cache *FileCache) DropAll() {
	cache.mu.Lock()
	atomic.AddInt64(&cache.purgedCount, int64(len(cache.table)))
	atomic.StoreInt64(&cache.totalSizeOnDisk, 0)

	cache.table = make(map[common.SHA256]cachedFile, 128*1024)
	cache.lruHead = nil
	cache.lruHead = nil
	_ = os.RemoveAll(cache.cacheDir)
	_ = createSubdirsForFileCache(cache.cacheDir)

	cache.mu.Unlock()
}

func (cache *FileCache) purgeLastElementsTillLimit(cacheLimit int64) {
	for atomic.LoadInt64(&cache.totalSizeOnDisk) > cacheLimit {
		var removingFile cachedFile
		cache.mu.Lock()
		if tail := cache.lruTail; tail != nil && tail.prev != nil {
			cache.lruTail = tail.prev
			cache.lruTail.next = nil
			removingFile = cache.table[tail.key]
			delete(cache.table, tail.key)
		}
		cache.mu.Unlock()

		if removingFile.lruNode != nil {
			_ = os.Remove(removingFile.pathInCache)
			atomic.AddInt64(&cache.totalSizeOnDisk, -removingFile.fileSize)
			atomic.AddInt64(&cache.purgedCount, 1)
		}
	}
}

